 if(state.accessory==='earrings')accessory='<g fill="none" stroke="#e9c578" stroke-width="2.5"><ellipse cx="-14" cy="-57" rx="3" ry="5"/><ellipse cx="15" cy="-57" rx="3" ry="5"/></g>';
 if(state.accessory==='necklace')accessory='<path d="M-7-48q8 15 15 0" fill="none" stroke="#e5c37b" stroke-width="1.5"/><path d="m1-38 3 5-3 3-3-3Z" fill="#e8ce8c"/>';
 if(state.accessory==='skateboard'){const riding=npc&&(state.mode==='skating'||state.mode==='walking');accessory=riding?'<g class="skate-prop"><path d="M-24 2q-9-5 1-9l43 1q14 3 3 10Z" fill="#bd8d62" stroke="#dfba81"/><circle cx="-15" cy="7" r="3" fill="#29434d"/><circle cx="16" cy="8" r="3" fill="#29434d"/><path d="M-5-5h11" stroke="#5b8c7d" stroke-width="4"/></g>':'<g transform="translate(23 -24) rotate(-16)"><rect x="-5" y="-24" width="11" height="47" rx="5" fill="#be9064" stroke="#e7c38f"/><path d="M-3-16h7M-3 14h7" stroke="#547d71" stroke-width="5"/><circle cx="-6" cy="-13" r="3" fill="#354854"/><circle cx="7" cy="12" r="3" fill="#354854"/></g>';}
 if(npc&&state.mode==='music')accessory+='<g class="sax-prop" transform="translate(12 -40)"><path d="M-7-13 0-9v23q0 17 13 9l7-10-11-4v11q-4 4-4-4V-11l-9-6" stroke="#e6bd65" stroke-width="5" fill="none" stroke-linejoin="round"/><ellipse cx="16" cy="12" rx="7" ry="4" fill="#f0d294" transform="rotate(-35 16 12)"/><path d="M1-1h4M1 5h4" stroke="#8a703d" stroke-width="2"/></g><text x="30" y="-68" fill="#e1c78b" font-size="17">♪</text>';
 // Femme-fatale look (Sofia): sleeveless crimson dress to the knee, evening gloves, heels, red lips,
 // side-swept waves, drop earrings and a cigarette in a long holder with drifting smoke.
 const fataleLegs='<g class="leg leg-left"><path d="M-8-22h5l-1 19h-4Z" fill="'+skin+'"/><path d="M-8-20l5 3M-8-15l5 3M-8-10l5 3M-3-20l-5 3M-3-15l-5 3M-3-10l-5 3" stroke="#141014" stroke-opacity=".55" stroke-width=".5"/><path d="M-10-4h7l2 4h-11Z" fill="#141014"/><path d="M-9 0v3" stroke="#141014" stroke-width="1.5"/></g><g class="leg leg-right"><path d="M3-22h5l1 19H4Z" fill="'+skin+'"/><path d="M3-20l5 3M3-15l5 3M3-10l5 3M8-20l-5 3M8-15l-5 3M8-10l-5 3" stroke="#141014" stroke-opacity=".55" stroke-width=".5"/><path d="M3-4h7l3 4H3Z" fill="#141014"/><path d="M11 0v3" stroke="#141014" stroke-width="1.5"/></g>';
 const fataleBody=`<path d="M-12-47-17-39l2 17 5 1 1-23M12-47l6 9-1 15-5 1-1-23" fill="${skin}"/><path d="M-17-27l1 5q3 4 7 0l-1-6M12-27l-1 7q5 3 8-2l-1-6" fill="#141014"/><path d="M-10-50q10-5 20 0l-2 14 6 30q-14 7-28 0l6-30Z" fill="${body}"/><path d="M-5-50 0-38 5-50Z" fill="${skin}"/><path d="M3-27 8-6h-4Z" fill="${skin}"/><path d="M4-20l3 2M4-15l4 2M5-10l3 2" stroke="#141014" stroke-opacity=".5" stroke-width=".5"/><g class="boa" fill="#f28bb5"><circle cx="-15" cy="-46" r="3.2"/><circle cx="-11" cy="-49" r="3.4"/><circle cx="-6" cy="-51" r="3"/><circle cx="6" cy="-51" r="3"/><circle cx="11" cy="-49" r="3.4"/><circle cx="15" cy="-46" r="3.2"/><circle cx="-17" cy="-41" r="2.8"/><circle cx="-18" cy="-36" r="2.6"/><circle cx="17" cy="-41" r="2.8"/><circle cx="18" cy="-36" r="2.6"/><circle cx="18" cy="-31" r="2.3"/></g><g fill="#f7b3cf"><circle cx="-12" cy="-50" r="1.4"/><circle cx="11" cy="-50" r="1.4"/><circle cx="-17" cy="-38" r="1.2"/><circle cx="18" cy="-33" r="1.1"/></g>`;
